import {membership,customer,loadMembership,APP_ORIGIN,modelOptions} from './membership.js';
import {list,read,clearLocalData,legacyLibrary,importLegacyLibrary} from './project-store.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const link=(text,href,cls='')=>{const a=el('a',cls,text);a.href=href;return a};
const button=(text,fn,cls='ws-outline')=>{const b=el('button',cls,text);b.type='button';b.onclick=fn;return b};
const loginURL=()=>APP_ORIGIN+'/signin-with-chatgpt?return_to='+encodeURIComponent('/account.html');
const download=(data,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=link('',url);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function title(root,h,p){root.append(el('h1','',h),el('p','account-lead',p))}
export function loginScreen(root){
 const frame=el('section','login-layout'),copy=el('div','login-copy');copy.append(el('h1','','Твои проекты. Твой аккаунт.'),el('p','','Войди через ChatGPT. Подписка, доступ к моделям и история платежей будут связаны с твоим аккаунтом.'));
 const panel=el('section','login-panel');panel.append(el('h2','','Вход и регистрация'),el('p','','Один способ входа, без отдельного пароля VMET.'),link('Продолжить через ChatGPT',loginURL(),'ws-primary'),el('p','login-note','При первом входе создаётся бесплатный аккаунт. Создание видео доступно после активации подписки.'),link('Посмотреть тарифы','pricing.html','ws-text-link'));
 const info=el('details','data-disclosure');info.append(el('summary','','Что сохраняется'),el('p','','Сервер хранит email входа, имя, подписку, лимиты и историю операций. Исходники и монтажные проекты остаются в браузере на текущем домене. При переходе на другой домен библиотека автоматически не переносится.'));
 panel.append(info);frame.append(copy,panel);root.append(frame);legacyRecovery(root);
}
export async function accountScreen(root){
 const m=membership();if(!m.authenticated){loginScreen(root);if(m.connectionError)root.append(el('p','account-error',m.connectionError));return}
 title(root,'Личный кабинет','Профиль, доступ и данные твоей студии.');
 const navigation=el('nav','account-tabs');navigation.setAttribute('aria-label','Разделы аккаунта');const content=el('section','account-content');
 const tabs=[['profile','Профиль'],['subscription','Подписка'],['security','Безопасность'],['data','Мои данные']];
 const status=el('p','account-status');status.role='status';root.append(navigation,status,content);
 let record;
 const date=value=>value?new Date(value).toLocaleString('ru-RU',{timeZone:record?.profile.timezone||'UTC',dateStyle:'medium',timeStyle:'short'}):'Нет';
 async function load(){status.textContent='Загружаем данные аккаунта…';content.setAttribute('aria-busy','true');try{record=await customer('/api/account');status.textContent='';render(location.hash.slice(1)||'profile')}catch(e){status.textContent=e.message;content.replaceChildren(button('Повторить загрузку',load))}finally{content.removeAttribute('aria-busy')}}
 function render(tab){content.replaceChildren();navigation.replaceChildren();for(const[id,label]of tabs){const a=link(label,'#'+id,tab===id?'selected':'');a.setAttribute('aria-current',tab===id?'page':'false');a.onclick=e=>{e.preventDefault();history.replaceState(null,'','#'+id);render(id)};navigation.append(a)}
  if(tab==='subscription'){
   const section=el('section','account-subscription');section.append(el('h2','',m.plan==='free'?'Только просмотр':m.plan[0].toUpperCase()+m.plan.slice(1)),el('p','',m.canCreate?'Доступ до '+date(m.endsAt):'Создание открывается на Lite, Plus или Pro.'));
   if(m.canCreate){const bar=el('progress');bar.max=m.videoLimit;bar.value=m.videosUsed;bar.setAttribute('aria-label','Использовано видеопроектов');section.append(bar,el('p','usage-reading',`${m.videosUsed} из ${m.videoLimit} видео за ${m.periodDays} дней`),el('p','account-note','Слот учитывается при создании проекта. Правки и повторные экспорты не расходуют новые слоты.'))}
   section.append(link('Управлять подпиской','pricing.html','ws-primary'));content.append(section);
   const ledger=el('section','account-section');ledger.append(el('h2','','Операции с кредитами'));ledger.append(table(['Изменение','Основание','Дата'],record.ledger.map(l=>[String(l.amount),l.reason,date(l.created_at)]),'Операций пока нет.'));content.append(ledger);
   const orders=el('section','account-section');orders.append(el('h2','','Платёжные счета'));orders.append(el('p','','Счета и проверка оплаты доступны на странице подписки.'),link('Открыть счета','pricing.html','ws-text-link'));content.append(orders);
  }else if(tab==='security'){
   const section=el('section','account-section');section.append(el('h2','','Вход через ChatGPT'),el('p','','Email: '+record.user.email),el('p','account-note','Пароль VMET не создаётся. Сеанс и восстановление доступа управляются аккаунтом ChatGPT. Список чужих устройств здесь не имитируется.'),link('Выйти из текущего сеанса',APP_ORIGIN+'/signout-with-chatgpt','ws-outline'));content.append(section);
   const tokens=el('section','account-section');tokens.append(el('h2','','API-токены'));if(!record.tokens.length)tokens.append(el('p','','Выпущенных токенов нет. Для чата в студии достаточно входа и активной подписки.'));
   for(const t of record.tokens){const row=el('div','account-token');row.append(el('div','',t.name),el('code','',t.prefix+'…'),el('span','',t.revoked?'Отозван':t.expires_at<new Date().toISOString()?'Истёк':'Действует до '+date(t.expires_at)));if(!t.revoked)row.append(button('Отозвать',()=>confirmAction('Отозвать токен',t.name,async()=>{await customer('/api/account/revoke-token',{id:t.id});await load()})));tokens.append(row)}content.append(tokens);
   if(record.user.role!=='owner'){const danger=el('details','account-danger');danger.append(el('summary','','Приостановить аккаунт'));danger.append(el('p','','Доступ и все API-токены будут отключены. Остаток подписки не возвращается автоматически. Финансовая история сохраняется; восстановление выполняет администратор. Незавершённые платежи сначала требуют проверки.'));danger.append(button('Приостановить аккаунт',()=>confirmAction('Приостановить аккаунт',record.user.email,async()=>{await customer('/api/account/deactivate',{confirm:record.user.email});location.href=APP_ORIGIN+'/signout-with-chatgpt'},true)));content.append(danger)}
  }else if(tab==='data'){
   const remote=el('section','account-section');remote.append(el('h2','','Данные аккаунта'),el('p','','Имя, настройки, подписка и история операций. API-секреты в выгрузку не входят.'),button('Скачать данные аккаунта',async()=>{try{download(await customer('/api/account/export'),'vmet-account.json');status.textContent='Файл данных подготовлен для скачивания.'}catch(e){status.textContent=e.message}},'ws-primary'));content.append(remote);
   const local=el('section','account-section');local.append(el('h2','','Проекты в этом браузере'),el('p','','Исходники и композиции хранятся на этом устройстве и домене. Выход из аккаунта их не удаляет. На общем компьютере сделай резервную копию и очисти локальные данные.'));
   local.append(button('Скачать локальные проекты',async()=>{try{const records=(await list()).filter(x=>x&&typeof x==='object'&&(x.version===1||x.checkpointId));download({version:1,exportedAt:new Date().toISOString(),projectsAndCheckpoints:records,brandKit:await read('brand-kit'),note:'Без исходных медиа. Для открытия отдельного проекта импортируйте его JSON и исходники.'},'vmet-local-projects-backup.json');status.textContent='Резервная копия подготовлена. Медиа нужно сохранить отдельно.'}catch(e){status.textContent=e.message}}));
   const details=el('details','account-danger');details.append(el('summary','','Очистить данные этого браузера'),el('p','','Будут удалены локальные проекты, медиа, бренд-кит и контрольные точки этого домена. Серверный аккаунт и платежи останутся. Сначала сохрани JSON и оригиналы.'));details.append(button('Очистить локальные данные',()=>confirmAction('Очистить локальные данные','УДАЛИТЬ',async()=>{await clearLocalData();location.reload()},true)));local.append(details);content.append(local);legacyRecovery(content);
  }else{
   const form=el('form','profile-form');form.innerHTML='<h2>Профиль</h2><label>Имя<input name="name" maxlength="70" required autocomplete="name"></label><label>Email входа<input name="email" type="email" readonly></label><p class="account-note">Email берётся из ChatGPT. Его нельзя заменить, чтобы получить доступ к другому аккаунту.</p><label>Часовой пояс кабинета<input name="timezone" list="timezones" required placeholder="Europe/Moscow"></label><datalist id="timezones"><option value="Europe/Moscow"><option value="Asia/Krasnoyarsk"><option value="Asia/Yekaterinburg"><option value="UTC"></datalist><label>Модель по умолчанию<select name="default_model"></select></label><p class="account-note">Доступность модели всё равно определяется подпиской и настройками администратора.</p><button class="ws-primary" type="submit">Сохранить профиль</button><p role="status" id="profile-message" class="profile-message"></p>';
   for(const field of form.querySelectorAll('input,select')){field.setAttribute('aria-describedby','profile-message');field.oninput=()=>field.removeAttribute('aria-invalid')}form.elements.name.value=record.user.name;form.elements.email.value=record.user.email;form.elements.timezone.value=record.profile.timezone;modelOptions(form.elements.default_model,record.profile.default_model);
   form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]'),message=form.querySelector('.profile-message');b.disabled=true;message.textContent='Сохраняем…';try{const r=await customer('/api/account/profile',Object.fromEntries(new FormData(form)));record.user.name=r.name;record.profile=r.profile;await loadMembership();const header=document.querySelector('.header-account-name');if(header)header.textContent=r.name;message.textContent='Профиль сохранён.'}catch(e){message.textContent=e.message;if(e.message.includes('Имя'))form.elements.name.setAttribute('aria-invalid','true');if(e.message.includes('пояс'))form.elements.timezone.setAttribute('aria-invalid','true')}finally{b.disabled=false}};
   const info=el('aside','profile-context');info.append(el('h2','','Один аккаунт для студии'),el('p','','Подписка и платежи синхронизируются на сервере. Монтажные файлы остаются в браузере.'),el('dl'));for(const[k,v]of [['Аккаунт создан',date(record.user.createdAt)],['Вход','ChatGPT'],['Тариф',m.plan==='free'?'Free':m.plan[0].toUpperCase()+m.plan.slice(1)]]){info.lastChild.append(el('dt','',k),el('dd','',v))}const grid=el('div','profile-grid');grid.append(form,info);content.append(grid);
  }
 }
 await load();
}
function table(head,rows,empty){if(!rows.length)return el('p','',empty);const wrap=el('div','table-wrap'),table=el('table'),h=el('thead'),tr=el('tr');head.forEach(x=>tr.append(el('th','',x)));h.append(tr);const body=el('tbody');for(const r of rows){const row=el('tr');r.forEach(x=>row.append(el('td','',x)));body.append(row)}table.append(h,body);wrap.append(table);return wrap}
function confirmAction(title,value,action,type=false){const d=el('dialog','ws-dialog'),form=el('form');form.append(el('h2','',title),el('p','','Подтверждение: '+value));let input;if(type){const label=el('label','','Введите подтверждение');input=el('input');input.required=true;input.autocomplete='off';label.append(input);form.append(label)}const error=el('p','account-error');error.role='alert';const actions=el('div','ws-dialog-actions');actions.append(button('Отмена',()=>d.close()));const submit=el('button','ws-primary','Подтвердить');submit.type='submit';actions.append(submit);form.append(error,actions);form.onsubmit=async e=>{e.preventDefault();if(type&&input.value!==value){error.textContent='Подтверждение не совпадает.';return}submit.disabled=true;try{await action();d.close()}catch(e){error.textContent=e.message}finally{submit.disabled=false}};d.append(form);document.body.append(d);d.onclose=()=>d.remove();d.showModal()}

function legacyRecovery(root){const details=el('details','data-disclosure legacy-recovery');details.append(el('summary','','Старая библиотека этого браузера'));const box=el('div');details.append(box);let loaded=false;details.ontoggle=async()=>{if(!details.open||loaded)return;loaded=true;box.append(el('p','','Старые проекты не присваиваются аккаунту автоматически. Здесь можно сохранить JSON без исходных файлов. Библиотеки других доменов недоступны.'));try{const old=await legacyLibrary();const projects=(old?.projects||[]).filter(p=>p&&p.version===1);const seen=new Set();for(const p of projects){const key=p.projectId||'current';if(seen.has(key))continue;seen.add(key);const row=el('div','account-token');row.append(el('span','',p.name||'Старый проект'),button('Скачать JSON',()=>download({...p,assetManifest:[...old.assets.map(a=>({id:a.id,name:a.name,type:a.type,duration:a.duration})),...['motion','type','story'].map((k,i)=>({id:'demo-'+k,name:['Every frame matters','Make it move','Новый ракурс'][i],type:'video',duration:6,builtin:true}))]},'vmet-recovered-project.json')));box.append(row)}if(!seen.size)box.append(el('p','','Старая библиотека на этом домене не найдена.'));if(seen.size&&membership().user?.role==='owner')box.append(button('Перенести в мой аккаунт',()=>confirmAction('Перенести старую библиотеку','ПЕРЕНЕСТИ',async()=>{const n=await importLegacyLibrary();box.append(el('p','',n+' проектов восстановлено. Исходная библиотека не удалена.'))},true)))}catch(e){box.append(el('p','account-error',e.message))}};root.append(details)}
